function ToggleAbstract(){const e=document.getElementById("abstract-1"),t=document.getElementById("abstract_button_1");e.classList.contains("hidden")?t.setAttribute("title","Hide abstract"):t.setAttribute("title","Show abstract"),e.classList.toggle("hidden")}document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("abstract_button_1");e&&e.addEventListener("click",ToggleAbstract)})